/// Register-level description of a regular (text) GBA background.  The
/// opening scenes historically carried hand-sliced tile and screen assets,
/// but the overworld needs the real control/scroll path: its visible terrain
/// is assembled from several text layers with independent priorities.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct GbaTextBg {
    /// Hardware BG index (0 through 3).  When two text backgrounds share a
    /// priority, the lower numbered BG is in front on the GBA PPU.
    bg_index: u8,
    control: u16,
    scroll_x: u16,
    scroll_y: u16,
    transparent_zero: bool,
}

/// The GBA's two rectangular windows plus the control bits that select them.
/// Values are the raw little-endian IO register values, so a provenance
/// capture can be passed through without scene-specific coordinate rewriting.
#[allow(dead_code)] // Activated by opt-in receipt-backed PPU captures.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct GbaWindowRegisters {
    dispcnt: u16,
    win0h: u16,
    win1h: u16,
    win0v: u16,
    win1v: u16,
    winin: u16,
    winout: u16,
}

/// Per-pixel layer-enable bits resolved from the GBA window registers.
/// Bits 0..=3 are BG0..=BG3 and bit 4 is OBJ; bit 5 (special effects) is
/// retained for a later BLDCNT/BLDALPHA stage.
#[derive(Clone, Debug, PartialEq, Eq)]
struct GbaWindowMask {
    layer_masks: Vec<u8>,
}

/// Raw mode-0 PPU registers required to reproduce a regular text-BG/OBJ
/// frame. This is intentionally data-only: callers provide live engine state
/// or an external receipt, never a scene-specific screenshot or asset patch.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct GbaPpuRegisters {
    pub dispcnt: u16,
    pub bgcnt: [u16; 4],
    /// BG0HOFS, BG0VOFS, BG1HOFS, BG1VOFS, ... BG3VOFS.
    pub bg_offsets: [u16; 8],
    pub win0h: u16,
    pub win1h: u16,
    pub win0v: u16,
    pub win1v: u16,
    pub winin: u16,
    pub winout: u16,
}

impl GbaPpuRegisters {
    /// Keep write-only BGxHOFS/VOFS in engine state. Reading the IO latch is
    /// not a valid way to recover the value after a DMA/task handoff.
    pub fn set_bg_scroll(
        &mut self,
        bg_index: usize,
        horizontal: u16,
        vertical: u16,
    ) -> Result<(), String> {
        let offsets = self
            .bg_offsets
            .get_mut(bg_index * 2..bg_index * 2 + 2)
            .ok_or_else(|| "GBA background index must be in 0..=3".to_owned())?;
        offsets.copy_from_slice(&[horizontal, vertical]);
        Ok(())
    }
}

/// Logical battle BG0 surfaces own their write-only scroll value. These are
