impl BattleMode0Surface {
    pub fn bg0_vertical_offset(self) -> u16 {
        match self {
            Self::Command => 160,
            Self::MoveSelection => 320,
        }
    }

    pub fn apply_scroll_shadow(self, registers: &mut GbaPpuRegisters) -> Result<(), String> {
        registers.set_bg_scroll(0, 0, self.bg0_vertical_offset())
    }
}

/// Mutable GBA mode-0 memory owned by the engine. Uploads are range-checked
/// and separate BG/OBJ/palette/OAM address spaces, which makes a logical
/// battle state feed the compositor without retaining an emulator snapshot.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GbaMode0PpuMemory {
    pub vram: Vec<u8>,
    pub palette: Vec<u8>,
    pub oam: Vec<u8>,
}

impl Default for GbaMode0PpuMemory {
    fn default() -> Self {
        Self {
            vram: vec![0; 0x18000],
            palette: vec![0; 0x400],
            oam: vec![0; 0x400],
        }
    }
}

impl GbaMode0PpuMemory {
    pub fn upload_bg_vram(&mut self, offset: usize, bytes: &[u8]) -> Result<(), String> {
        upload_ppu_bytes(&mut self.vram[..0x10000], offset, bytes, "BG VRAM")
    }

    pub fn upload_obj_vram(&mut self, offset: usize, bytes: &[u8]) -> Result<(), String> {
        upload_ppu_bytes(&mut self.vram[0x10000..], offset, bytes, "OBJ VRAM")
    }

    pub fn upload_bg_palette(&mut self, offset: usize, bytes: &[u8]) -> Result<(), String> {
        upload_ppu_bytes(&mut self.palette[..0x200], offset, bytes, "BG palette")
    }

    pub fn upload_obj_palette(&mut self, offset: usize, bytes: &[u8]) -> Result<(), String> {
        upload_ppu_bytes(&mut self.palette[0x200..], offset, bytes, "OBJ palette")
    }

    pub fn upload_oam(&mut self, offset: usize, bytes: &[u8]) -> Result<(), String> {
        upload_ppu_bytes(&mut self.oam, offset, bytes, "OAM")
    }

    pub fn render(&self, registers: GbaPpuRegisters) -> Result<Vec<u8>, String> {
        composite_gba_mode0_ppu_frame(&self.vram, &self.palette, &self.oam, registers)
    }

    /// Mirrors `CopyToBgTilemapBuffer`/`CopyBgTilemapBufferToVram` for one
    /// regular text-BG entry, including the hardware's 32x32 screenblock
    /// layout. Battle windows and text printers use this rather than RGB
    /// writes, so their state remains composable with scroll and priority.
    pub fn write_text_bg_entry(
        &mut self,
        registers: GbaPpuRegisters,
        bg_index: usize,
        tile_x: usize,
        tile_y: usize,
        entry: u16,
    ) -> Result<(), String> {
        let offset = gba_text_bg_entry_offset(registers, bg_index, tile_x, tile_y)?;
        self.vram[offset..offset + 2].copy_from_slice(&entry.to_le_bytes());
        Ok(())
    }

    /// Equivalent to a window buffer clear/copy: fill a tilemap rectangle
    /// with one tile/palette entry, clipping to the selected text BG size.
    pub fn fill_text_bg_rect(
        &mut self,
        registers: GbaPpuRegisters,
        bg_index: usize,
        tile_x: usize,
        tile_y: usize,
        width: usize,
        height: usize,
        entry: u16,
    ) -> Result<(), String> {
        gba_text_bg_rect_is_in_bounds(registers, bg_index, tile_x, tile_y, width, height)?;
        for y in tile_y..tile_y.saturating_add(height) {
            for x in tile_x..tile_x.saturating_add(width) {
                let offset = gba_text_bg_entry_offset(registers, bg_index, x, y)?;
                self.vram[offset..offset + 2].copy_from_slice(&entry.to_le_bytes());
            }
        }
        Ok(())
    }

    /// Copies a text-BG rectangle with the same palette mode used by
    /// `CopyToBgTilemapBufferRect_ChangePalette`.  Values 0..=15 replace the
    /// source entry's palette bank; 16 preserves the destination's bank and
    /// flips; 17 preserves the complete source entry.  The operation is
    /// range-checked before writing so invalid UI data cannot leave a partial
    /// tilemap update behind.
    pub fn copy_text_bg_rect_change_palette(
        &mut self,
        registers: GbaPpuRegisters,
        bg_index: usize,
        source: &[u16],
        tile_x: usize,
        tile_y: usize,
        width: usize,
        height: usize,
        palette_mode: u8,
    ) -> Result<(), String> {
        let count = width
            .checked_mul(height)
            .ok_or_else(|| "text BG rectangle size overflows".to_owned())?;
        if source.len() < count {
            return Err("text BG copy source is shorter than its rectangle".to_owned());
        }
        gba_text_bg_rect_is_in_bounds(registers, bg_index, tile_x, tile_y, width, height)?;
        for (index, source_entry) in source.iter().take(count).enumerate() {
            let x = tile_x + index % width;
            let y = tile_y + index / width;
            let offset = gba_text_bg_entry_offset(registers, bg_index, x, y)?;
            let destination = u16::from_le_bytes([self.vram[offset], self.vram[offset + 1]]);
            let entry = match palette_mode {
                0..=15 => (source_entry & 0x0fff) | (u16::from(palette_mode) << 12),
                16 => (destination & 0xfc00) | (source_entry & 0x03ff),
                _ => *source_entry,
            };
            self.vram[offset..offset + 2].copy_from_slice(&entry.to_le_bytes());
        }
        Ok(())
    }

    /// Replays `DrawTextBorderOuter` for a normal text BG. `tile_num` is the
    /// first of the source frame's nine border tiles and `palette_num` is the
    /// 4bpp palette bank passed by the caller.
    pub fn draw_text_window_outer_border(
        &mut self,
        registers: GbaPpuRegisters,
        window: GbaTextWindow,
        tile_num: u16,
        palette_num: u8,
    ) -> Result<(), String> {
        let (left, top) = window.outer_origin()?;
        let full_width = window
            .width
            .checked_add(2)
            .ok_or_else(|| "text window width overflows".to_owned())?;
        let full_height = window
            .height
            .checked_add(2)
            .ok_or_else(|| "text window height overflows".to_owned())?;
        gba_text_bg_rect_is_in_bounds(
            registers,
            window.bg_index,
            left,
            top,
            full_width,
            full_height,
        )?;
        let entry =
            |offset: u16| tile_num.wrapping_add(offset) | (u16::from(palette_num & 0x0f) << 12);
        self.fill_text_bg_rect(registers, window.bg_index, left, top, 1, 1, entry(0))?;
        self.fill_text_bg_rect(
            registers,
            window.bg_index,
            window.tilemap_left,
            top,
            window.width,
            1,
            entry(1),
        )?;
        self.fill_text_bg_rect(
            registers,
            window.bg_index,
            window.tilemap_left + window.width,
            top,
            1,
            1,
            entry(2),
        )?;
        self.fill_text_bg_rect(
            registers,
            window.bg_index,
            left,
            window.tilemap_top,
            1,
            window.height,
            entry(3),
        )?;
        self.fill_text_bg_rect(
            registers,
            window.bg_index,
            window.tilemap_left + window.width,
            window.tilemap_top,
            1,
            window.height,
            entry(5),
        )?;
        self.fill_text_bg_rect(
            registers,
            window.bg_index,
            left,
            window.tilemap_top + window.height,
            1,
            1,
            entry(6),
        )?;
        self.fill_text_bg_rect(
            registers,
            window.bg_index,
            window.tilemap_left,
            window.tilemap_top + window.height,
            window.width,
            1,
            entry(7),
        )?;
        self.fill_text_bg_rect(
            registers,
            window.bg_index,
            window.tilemap_left + window.width,
            window.tilemap_top + window.height,
            1,
            1,
            entry(8),
        )
    }

    /// Replays `rbox_fill_rectangle`: clear the window and its one-tile outer
    /// border using a caller-owned tile/palette entry.
    pub fn clear_text_window_outer(
        &mut self,
        registers: GbaPpuRegisters,
        window: GbaTextWindow,
        entry: u16,
    ) -> Result<(), String> {
        let (left, top) = window.outer_origin()?;
        let width = window
            .width
            .checked_add(2)
            .ok_or_else(|| "text window width overflows".to_owned())?;
        let height = window
            .height
            .checked_add(2)
            .ok_or_else(|| "text window height overflows".to_owned())?;
        self.fill_text_bg_rect(registers, window.bg_index, left, top, width, height, entry)
    }

    /// Replays `CopyWindowToVram(..., COPYWIN_GFX)` for a 4bpp text window.
    /// The caller supplies the text-printer's packed tile buffer (including
    /// its fill color and glyph pixels); this engine writes it only to the
    /// source template's base tile range.
    pub fn upload_text_window_tiles(
        &mut self,
        registers: GbaPpuRegisters,
        window: GbaTextWindow,
        packed_4bpp_tiles: &[u8],
    ) -> Result<(), String> {
        let control = *registers
            .bgcnt
            .get(window.bg_index)
            .ok_or_else(|| "GBA background index must be in 0..=3".to_owned())?;
        if control & (1 << 7) != 0 {
            return Err("text-window tile uploads require a 4bpp text BG".to_owned());
        }
        let tile_count = window
            .width
            .checked_mul(window.height)
            .ok_or_else(|| "text window tile count overflows".to_owned())?;
        let byte_count = tile_count
            .checked_mul(32)
            .ok_or_else(|| "text window tile byte count overflows".to_owned())?;
        if packed_4bpp_tiles.len() != byte_count {
            return Err(
                "text-window tile buffer length does not match its WindowTemplate".to_owned(),
            );
        }
        let char_base = usize::from((control >> 2) & 0x03) * 0x4000;
        let offset = char_base
            .checked_add(usize::from(window.base_tile) * 32)
            .ok_or_else(|| "text-window tile offset overflows".to_owned())?;
        self.upload_bg_vram(offset, packed_4bpp_tiles)
    }

    /// Replays `PutWindowTilemap`: point every cell of the WindowTemplate at
    /// its consecutively uploaded tile, preserving the template's palette
    /// bank.  This is separate from glyph upload so one logical UI state has
    /// one explicit DMA-like graphics write and one explicit tilemap write.
    pub fn put_text_window_tilemap(
        &mut self,
        registers: GbaPpuRegisters,
        window: GbaTextWindow,
    ) -> Result<(), String> {
        if window.palette_num > 15 {
            return Err("text window palette must be a 4bpp bank in 0..=15".to_owned());
        }
        let count = window
            .width
            .checked_mul(window.height)
            .ok_or_else(|| "text window tile count overflows".to_owned())?;
        let end_tile = usize::from(window.base_tile)
            .checked_add(count)
            .ok_or_else(|| "text window tile range overflows".to_owned())?;
        if end_tile > 1024 {
            return Err("text window tile range exceeds a 4bpp text-BG character block".to_owned());
        }
        let entries: Vec<u16> = (0..count)
            .map(|index| (window.base_tile + index as u16) | (u16::from(window.palette_num) << 12))
            .collect();
        self.copy_text_bg_rect_change_palette(
            registers,
            window.bg_index,
            &entries,
            window.tilemap_left,
            window.tilemap_top,
            window.width,
            window.height,
            17,
        )
    }

    /// Source-derived action cursor writer. Emerald stores tiles `[1, 2]` at
    /// `(16 + 7 * (cursor & 1), 35 + (cursor & 2))` using palette mode 17,
    /// which preserves the two source entries exactly.
    pub fn write_emerald_action_selection_cursor(
        &mut self,
        registers: GbaPpuRegisters,
        cursor: u8,
    ) -> Result<(), String> {
        if cursor > 3 {
            return Err("Emerald action-selection cursor must be in 0..=3".to_owned());
        }
        let source = [1_u16, 2_u16];
        self.copy_text_bg_rect_change_palette(
            registers,
            0,
            &source,
            16 + 7 * usize::from(cursor & 1),
            35 + usize::from(cursor & 2),
            1,
            2,
            17,
        )
    }

    /// Replays `ActionSelectionDestroyCursorAt`. The source clears every
    /// command slot before creating the selected cursor, so the central menu
    /// divider at x=23 remains tile `0x1016` rather than a window-buffer
    /// tile. This order is observable in the authenticated BG0 receipt.
    pub fn clear_emerald_action_selection_cursor(
        &mut self,
        registers: GbaPpuRegisters,
        cursor: u8,
    ) -> Result<(), String> {
        if cursor > 3 {
            return Err("Emerald action-selection cursor must be in 0..=3".to_owned());
        }
        let source = [0x1016_u16, 0x1016_u16];
        self.copy_text_bg_rect_change_palette(
            registers,
            0,
            &source,
            16 + 7 * usize::from(cursor & 1),
            35 + usize::from(cursor & 2),
            1,
            2,
            17,
        )
    }

    /// Replays `MoveSelectionCreateCursorAt(..., 0)`.  The move page lives
    /// in the lower half of BG0's 64-tile map, not at the action-menu rows.
    pub fn write_emerald_move_selection_cursor(
        &mut self,
        registers: GbaPpuRegisters,
        cursor: u8,
    ) -> Result<(), String> {
        if cursor > 3 {
            return Err("Emerald move-selection cursor must be in 0..=3".to_owned());
        }
        let source = [1_u16, 2_u16];
        self.copy_text_bg_rect_change_palette(
            registers,
            0,
            &source,
            1 + 9 * usize::from(cursor & 1),
            55 + usize::from(cursor & 2),
            1,
            2,
            17,
        )
    }

    /// Replays `MoveSelectionDestroyCursorAt` before a new move cursor is
    /// written.  The source restores the textbox divider tile in this slot.
    pub fn clear_emerald_move_selection_cursor(
        &mut self,
        registers: GbaPpuRegisters,
        cursor: u8,
    ) -> Result<(), String> {
        if cursor > 3 {
            return Err("Emerald move-selection cursor must be in 0..=3".to_owned());
        }
        let source = [0x1016_u16, 0x1016_u16];
        self.copy_text_bg_rect_change_palette(
            registers,
            0,
            &source,
            1 + 9 * usize::from(cursor & 1),
            55 + usize::from(cursor & 2),
            1,
            2,
            17,
        )
    }
}

fn upload_ppu_bytes(
    target: &mut [u8],
    offset: usize,
    bytes: &[u8],
    label: &str,
) -> Result<(), String> {
    let end = offset
        .checked_add(bytes.len())
        .ok_or_else(|| format!("{label} upload overflows"))?;
    let destination = target
        .get_mut(offset..end)
        .ok_or_else(|| format!("{label} upload is out of range"))?;
    destination.copy_from_slice(bytes);
    Ok(())
}

fn gba_text_bg_entry_offset(
    registers: GbaPpuRegisters,
    bg_index: usize,
    tile_x: usize,
    tile_y: usize,
) -> Result<usize, String> {
    let control = *registers
        .bgcnt
        .get(bg_index)
        .ok_or_else(|| "GBA background index must be in 0..=3".to_owned())?;
    let (width, height, blocks_per_row) = gba_text_bg_dimensions(control);
    if tile_x >= width || tile_y >= height {
        return Err("text BG tilemap coordinate is outside its screen size".to_owned());
    }
    let screen_base = usize::from((control >> 8) & 0x1f) * 0x800;
    let block = tile_x / 32 + (tile_y / 32) * blocks_per_row;
    Ok(screen_base + block * 0x800 + ((tile_y % 32) * 32 + tile_x % 32) * 2)
}

fn gba_text_bg_dimensions(control: u16) -> (usize, usize, usize) {
    match (control >> 14) & 0x03 {
        0 => (32, 32, 1),
        1 => (64, 32, 2),
        2 => (32, 64, 1),
        3 => (64, 64, 2),
        _ => unreachable!(),
    }
}

fn gba_text_bg_rect_is_in_bounds(
    registers: GbaPpuRegisters,
    bg_index: usize,
    tile_x: usize,
    tile_y: usize,
    width: usize,
    height: usize,
) -> Result<(), String> {
    let control = *registers
        .bgcnt
        .get(bg_index)
        .ok_or_else(|| "GBA background index must be in 0..=3".to_owned())?;
    let (map_width, map_height, _) = gba_text_bg_dimensions(control);
    let right = tile_x
        .checked_add(width)
        .ok_or_else(|| "text BG rectangle x overflows".to_owned())?;
    let bottom = tile_y
        .checked_add(height)
        .ok_or_else(|| "text BG rectangle y overflows".to_owned())?;
    if right > map_width || bottom > map_height {
        return Err("text BG rectangle is outside its screen size".to_owned());
    }
    Ok(())
}

