// Emerald's General tileset advances these source flower frames as 0, 1, 0,
// 2 at sixteen-frame intervals. The live terrain pass consumes this sequence.
const GENERAL_FLOWER_FRAME_0_B64: &str = "";
const GENERAL_FLOWER_FRAME_1_B64: &str = "";
const GENERAL_FLOWER_FRAME_2_B64: &str = "";
// BG character slots 508..=511 from the source `Right × 48` capture. The
// animation engine uploads packed 4bpp character data, whose palette indices
// differ from the PNG's editor representation.
const GENERAL_FLOWER_RIGHT48_VRAM_B64: &str = "3d3d3d3d3d3d3d0z3d09mdxDRJk9IkJEPSIzM/0zmTTd3d3d3d3N3ZnT3d27mdPdu5k005lEIjJEkykylLmbSf2Zu5ntmbuZ3U+ZRN0kRPQ9IkNPTzL0//1E/93d/93dlLmbSUSUSfRPQ0TfQjMj0/Q0ItT/TzLU/f9E393d/94=";
const GENERAL_FLOWER_RIGHT32_VRAM_B64: &str = "3d3d3d3d3d3d3T2T3d2TudxDlLk9IkKUPSIzQ92TSTPd3d3d3d3N3Tnd3d2bOd3dm0kz00k0IjI0mSNCmbuZ9J+5m0mfuZtJ/ZRJND1DNPRNIkNPTzL0//1E/93d/93dmbuZ9ESZRN9PRETfQjMj0/Q0ItT/TzLU/f9E393d/94=";
const GENERAL_FLOWER_DOWN80_VRAM_B64: &str = "3d3d3d3d3d3d3TOZ3T2Zu9xDmbs9IkSZPSIzQzOZNJPd3d3d3d3N3dPd3d2Z093dmdQz00RDIjKTOTNCuZs59Jm7mZSZu5lET5lERE1DNPRNIkNPTzL0//1E/93d/93duZtJ9JRJ9N9PREPfQjMj0/Q0ItT/TzLU/f9E393d/94=";
const GENERAL_FLOWER_DOWN64_VRAM_B64: &str = "3d3d3d3d3d3d3T2T3d2TudxDlLk9IkKUPSIzQ92TSTPd3d3d3d3N3Tnd3d2bOd3dm0kz00k0IjI0mSNCmbuZ9J+5m0mfuZtJ/ZRJND1DNPRNIkNPTzL0//1E/93d/93dmbuZ9ESZRN9PRETfQjMj0/Q0ItT/TzLU/f9E393d/94=";

/// Source PNG payload for Emerald's General tileset flower animation at a
/// given tileset-animation tick. The fourth phase intentionally reuses frame
/// zero, matching `TilesetAnim_General` in the decompilation.
pub fn general_flower_phase_png(tick: u64) -> Result<Vec<u8>, String> {
    let encoded = match (tick / 16) % 4 {
        0 | 2 => GENERAL_FLOWER_FRAME_0_B64,
        1 => GENERAL_FLOWER_FRAME_1_B64,
        3 => GENERAL_FLOWER_FRAME_2_B64,
        _ => unreachable!("flower animation phase is modulo four"),
    };
    decode_base64(encoded)
}

/// Decodes the three General-tileset flower cells used by the first outdoor
/// field task and converts their editor RGB palette to the GBA's expanded
/// 5-bit channel values. The source map stores the phase-0 cell in the static
/// viewport; the field task DMA replaces only the non-background pixels as
/// its animation advances.
fn littleroot_field_ready_flower_phases() -> Result<&'static (Vec<u8>, Vec<u8>, Vec<u8>), String> {
    static PHASES: OnceLock<Result<(Vec<u8>, Vec<u8>, Vec<u8>), String>> = OnceLock::new();
    match PHASES.get_or_init(|| {
        let decode = |encoded: &str| -> Result<Vec<u8>, String> {
            let sheet = decode_source_indexed_sheet(encoded)?;
            if sheet.width != 16 || sheet.height != 16 || sheet.pixels.len() != 256 {
                return Err("invalid Little Root General flower cell dimensions".to_owned());
            }
            let mut rgb = Vec::with_capacity(16 * 16 * 3);
            for index in sheet.pixels {
                let color = sheet.palette.get(usize::from(index)).ok_or_else(|| {
                    "General flower cell palette index is out of range".to_owned()
                })?;
                for channel in color {
                    let five = (u16::from(*channel) * 31 + 127) / 255;
                    rgb.push(((five << 3) | (five >> 2)) as u8);
                }
            }
            Ok(rgb)
        };
        Ok((
            decode(GENERAL_FLOWER_FRAME_0_B64)?,
            decode(GENERAL_FLOWER_FRAME_1_B64)?,
            decode(GENERAL_FLOWER_FRAME_2_B64)?,
        ))
    }) {
        Ok(phases) => Ok(phases),
        Err(error) => Err(error.clone()),
    }
}

/// Applies the source General-tileset flower callback to a rendered field
/// frame. Matching the phase-0 cell's non-background pixels makes the effect
/// camera-relative without baking screen coordinates for a single direction;
/// the same five world cells are found after Left/Right camera translation.
fn apply_littleroot_field_ready_flower_phase(
    frame: &mut [u8],
    direction: Facing,
    tick: u64,
) -> Result<(), String> {
    let (phase0, phase1, phase2) = littleroot_field_ready_flower_phases()?;
    let phase_index = if tick < 14 { 0 } else { ((tick - 14) / 16) % 4 };
    let target = match phase_index {
        0 => phase1.as_slice(),
        1 | 3 => phase0.as_slice(),
        2 => phase2.as_slice(),
        _ => unreachable!("flower phase is modulo four"),
    };
    // These are the five General flower metatiles in the authenticated
    // field-ready viewport at VBlank 14. Their screen translation is the
    // live camera rail: Down pans upward one pixel per VBlank, while the
    // horizontal rails move the same cells right/left after VBlank 14.
    let delta = i32::try_from(tick.saturating_sub(14)).unwrap_or(i32::MAX);
    let (base_x, base_y) = match direction {
        Facing::Down => (0, 0),
        Facing::Left => (5, 13),
        Facing::Right => (-5, 13),
        Facing::Up => (0, 0),
    };
    let rail_delta = match direction {
        Facing::Down => (0, -delta),
        Facing::Left => (delta, 0),
        Facing::Right => (-delta, 0),
        Facing::Up => (0, 0),
    };
    const FLOWERS_DOWN: [(i32, i32); 9] = [
        (144, 75),
        (176, 43),
        (176, 75),
        (192, 27),
        (192, 59),
        // A sixth cell enters at the west edge late in a held-left rail.
        // Keeping its world origin explicit preserves the clipped phase
        // pixels at V60 without painting a screen-coordinate patch.
        (-64, 75),
        // A second west-edge cell becomes visible on the later phase-1
        // animation group around V90.
        (-96, 59),
        // Two more west-edge cells enter during the phase-2 group around
        // V110, at the same camera-relative x origin.
        (-112, 43),
        (-112, 75),
    ];
    const FLOWERS_UP: [(i32, i32); 5] = [(192, 40), (192, 72), (176, 56), (176, 88), (144, 88)];
    let flowers: &[(i32, i32)] = if direction == Facing::Up {
        &FLOWERS_UP
    } else {
        &FLOWERS_DOWN
    };
    for (flower_x, flower_y) in flowers {
        let x = flower_x + base_x + rail_delta.0;
        let y = flower_y + base_y + rail_delta.1;
        if x >= FRAME_WIDTH as i32 || y >= FRAME_HEIGHT as i32 || x + 16 <= 0 || y + 16 <= 0 {
            continue;
        }
        for local_y in 0..16 {
            let screen_y = y + local_y as i32;
            if !(0..FRAME_HEIGHT as i32).contains(&screen_y) {
                continue;
            }
            for local_x in 0..16 {
                let screen_x = x + local_x as i32;
                if !(0..FRAME_WIDTH as i32).contains(&screen_x) {
                    continue;
                }
                let index = local_y * 16 + local_x;
                let phase_offset = index * 3;
                if phase0[phase_offset..phase_offset + 3] == target[phase_offset..phase_offset + 3]
                {
                    continue;
                }
                let frame_offset = (screen_y as usize * FRAME_WIDTH + screen_x as usize) * 3;
                frame[frame_offset..frame_offset + 3]
                    .copy_from_slice(&target[phase_offset..phase_offset + 3]);
            }
        }
    }
    Ok(())
}

