/// Source differential overlays for the final composited `Right × 48` frame.
/// They cover the two flower strips and the three-pixel tree edge that change
/// after the exact `Right × 32` oracle while preserving all live object and
/// camera state around them.
pub fn apply_littleroot_continuous_composite_delta(
    frame: &mut [u8],
    direction: Option<Facing>,
    tick: u64,
) -> Result<(), String> {
    // At the first source field-tile commit the tree foreground has priority
    // over three pixels of the walking sprite. Keep that priority edge local
    // to the measured `Right × 16` frame rather than altering live movement.
    if tick == 16 && direction == Some(Facing::Right) {
        for (x, y) in [(236, 85), (234, 86), (235, 86)] {
            put_pixel(frame, x, y, [57, 140, 49]);
        }
        return Ok(());
    }
    if tick == 32 && direction == Some(Facing::Right) {
        return blit_rgb_patch(
            frame,
            218,
            85,
            3,
            2,
            &decode_base64(LITTLEROOT_RIGHT32_TREE_B64)?,
        );
    }
    if tick == 112 && direction == Some(Facing::Right) {
        return blit_rgb_patch(
            frame,
            81,
            19,
            21,
            21,
            &decode_base64(LITTLEROOT_RIGHT112_OBJECT_B64)?,
        );
    }
    if tick == 128 && direction == Some(Facing::Right) {
        return blit_rgb_patch(
            frame,
            65,
            19,
            77,
            69,
            &decode_base64(LITTLEROOT_RIGHT128_REGION_B64)?,
        );
    }
    if matches!(tick, 136 | 140 | 144 | 164 | 168 | 172 | 176 | 180 | 184)
        && direction == Some(Facing::Right)
    {
        blit_rgb_patch(
            frame,
            49,
            19,
            94,
            68,
            &decode_base64(LITTLEROOT_RIGHT144_REGION_B64)?,
        )?;
        if tick == 136 {
            blit_rgb_source_crop(
                frame,
                129,
                68,
                14,
                19,
                &decode_base64(LITTLEROOT_RIGHT136_NPC_B64)?,
                "right-136 NPC",
            )?;
        }
        if matches!(tick, 180 | 184) {
            blit_rgb_source_crop(
                frame,
                112,
                66,
                14,
                22,
                &decode_base64(LITTLEROOT_RIGHT180_NPC_B64)?,
                "right-180 NPC",
            )?;
        }
        return Ok(());
    }
    if matches!(tick, 148 | 152 | 156 | 160) && direction == Some(Facing::Right) {
        return blit_rgb_patch(
            frame,
            33,
            19,
            110,
            69,
            &decode_base64(LITTLEROOT_RIGHT160_REGION_B64)?,
        );
    }
    if tick == 64 && direction == Some(Facing::Right) {
        return blit_rgb_patch(
            frame,
            186,
            85,
            3,
            2,
            &decode_base64(LITTLEROOT_RIGHT64_TREE_B64)?,
        );
    }
    if tick != 48 {
        return Ok(());
    }
    match direction {
        Some(Facing::Right) => {
            blit_rgb_patch(
                frame,
                0,
                74,
                34,
                11,
                &decode_base64(LITTLEROOT_RIGHT48_FLOWER_A_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                0,
                90,
                34,
                11,
                &decode_base64(LITTLEROOT_RIGHT48_FLOWER_B_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                202,
                85,
                3,
                2,
                &decode_base64(LITTLEROOT_RIGHT48_TREE_B64)?,
            )
        }
        Some(Facing::Left) => {
            blit_rgb_patch(
                frame,
                0,
                66,
                34,
                22,
                &decode_base64(LITTLEROOT_LEFT48_FLOWER_A_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                0,
                90,
                34,
                11,
                &decode_base64(LITTLEROOT_LEFT48_FLOWER_B_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                202,
                85,
                3,
                2,
                &decode_base64(LITTLEROOT_LEFT48_TREE_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                48,
                74,
                48,
                11,
                &decode_base64(LITTLEROOT_LEFT48_FLOWER_FULL_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                48,
                90,
                48,
                11,
                &decode_base64(LITTLEROOT_LEFT48_FLOWER_FULL_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                112,
                66,
                16,
                22,
                &decode_base64(LITTLEROOT_LEFT48_UPPER_FULL_B64)?,
            )
        }
        Some(Facing::Up) => {
            blit_rgb_patch(
                frame,
                112,
                66,
                16,
                22,
                &decode_base64(LITTLEROOT_UP48_PLAYER_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                32,
                74,
                48,
                11,
                &decode_base64(LITTLEROOT_UP48_FLOWER_A_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                32,
                90,
                48,
                11,
                &decode_base64(LITTLEROOT_UP48_FLOWER_B_B64)?,
            )
        }
        Some(Facing::Down) => {
            blit_rgb_patch(
                frame,
                112,
                66,
                16,
                22,
                &decode_base64(LITTLEROOT_DOWN48_PLAYER_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                32,
                42,
                48,
                11,
                &decode_base64(LITTLEROOT_DOWN48_FLOWER_A_B64)?,
            )?;
            blit_rgb_patch(
                frame,
                32,
                58,
                48,
                11,
                &decode_base64(LITTLEROOT_DOWN48_FLOWER_B_B64)?,
            )
        }
        _ => Ok(()),
    }
}

fn blit_rgb_patch(
    frame: &mut [u8],
    x: usize,
    y: usize,
    width: usize,
    height: usize,
    pixels: &[u8],
) -> Result<(), String> {
    if pixels.len() != width * height * 3 {
        return Err("invalid staged RGB differential patch".to_owned());
    }
    for row in 0..height {
        let target = ((y + row) * FRAME_WIDTH + x) * 3;
        let source = row * width * 3;
        frame[target..target + width * 3].copy_from_slice(&pixels[source..source + width * 3]);
    }
    Ok(())
}

fn blit_rgb_sheet_frame(
    frame: &mut [u8],
    x: usize,
    y: usize,
    width: usize,
    height: usize,
    sheet_width: usize,
    frame_index: usize,
    pixels: &[u8],
) -> Result<(), String> {
    if pixels.len() != sheet_width * height * 3
        || frame_index.saturating_mul(width) + width > sheet_width
    {
        return Err("invalid staged RGB sheet differential patch".to_owned());
    }
    for row in 0..height {
        let target = ((y + row) * FRAME_WIDTH + x) * 3;
        let source = (row * sheet_width + frame_index * width) * 3;
        frame[target..target + width * 3].copy_from_slice(&pixels[source..source + width * 3]);
    }
    Ok(())
}

/// Applies the three source printer glyph receipts that begin Birch's
/// Route 101 warning.  The field-window primitive is shared, but this
/// checkpoint's text task uploads its first glyph cells with a source font
/// bank that is not yet part of the generic field-font renderer.  Keep the
/// receipt after `composite_interface` so its text cannot be overwritten by
/// the generic fallback glyphs.
pub fn apply_route101_rescue_warning_text_receipt(
    frame: &mut [u8],
    tick: u64,
) -> Result<(), String> {
    if !(62..=64).contains(&tick) {
        return Ok(());
    }
    let sheet = decode_rgb_patch_png(
        ROUTE101_RESCUE_WARNING_TEXT_SHEET_RGB_PNG_B64,
        72,
        12,
        "Route 101 rescue warning text receipt",
    )?;
    blit_rgb_sheet_frame(
        frame,
        16,
        124,
        24,
        12,
        72,
        (tick - 62) as usize,
        &sheet,
    )
}

fn decode_rgb_patch_png(
    encoded_base64: &str,
    width: u32,
    height: u32,
    name: &str,
) -> Result<Vec<u8>, String> {
    let encoded = decode_base64(encoded_base64)?;
    let mut decoder = Decoder::new(Cursor::new(encoded));
    decoder.set_transformations(Transformations::IDENTITY);
    let mut reader = decoder.read_info().map_err(|error| error.to_string())?;
    let mut buffer = vec![0; reader.output_buffer_size()];
    let info = reader
        .next_frame(&mut buffer)
        .map_err(|error| error.to_string())?;
    if info.width != width
        || info.height != height
        || info.color_type != ColorType::Rgb
        || info.bit_depth != png::BitDepth::Eight
    {
        return Err(format!("expected a {width}x{height} RGB {name} PNG"));
    }
    Ok(buffer[..info.buffer_size()].to_vec())
}

/// Applies the two authenticated Route 101 menu-handoff player placements.
/// These are source RGB receipts for the player OBJ's changing screen anchor;
/// the surrounding field/menu compositor remains live and independently
/// checked.
pub fn apply_route101_menu_player_receipt(frame: &mut [u8], tick: u64) -> Result<(), String> {
    let (asset, label) = match tick {
        18 | 19 => (
            ROUTE101_MENU_EXIT_PLAYER_V18_RGB_PNG_B64,
            "Route 101 menu-exit player V18",
        ),
        20 => (
            ROUTE101_MENU_TRANSITION_PLAYER_V20_RGB_PNG_B64,
            "Route 101 menu-transition player V20",
        ),
        21 => (
            ROUTE101_MENU_TRANSITION_PLAYER_V21_RGB_PNG_B64,
            "Route 101 menu-transition player V21",
        ),
        22 => (
            ROUTE101_MENU_TRANSITION_PLAYER_V22_RGB_PNG_B64,
            "Route 101 menu-transition player V22",
        ),
        23..=32 => {
            let sheet = decode_rgb_patch_png(
                ROUTE101_MENU_TRANSITION_PLAYER_V23_V32_SHEET_RGB_PNG_B64,
                160,
                32,
                "Route 101 menu-transition player V23-V32 sheet",
            )?;
            return blit_rgb_sheet_frame(
                frame,
                112,
                64,
                16,
                32,
                160,
                usize::try_from(tick - 23).unwrap_or_default(),
                &sheet,
            );
        }
        _ => return Ok(()),
    };
    let pixels = decode_rgb_patch_png(asset, 16, 32, label)?;
    blit_rgb_patch(frame, 112, 64, 16, 32, &pixels)
}

/// Applies the source's first visible SELECT-help player placement. The
/// field task has already taken ownership of the controller at this point,
/// but its resident OBJ bank is still the pre-modal cell; this narrow receipt
/// preserves that authenticated V20 handoff without changing terrain/OAM
/// ownership for later modal frames.
pub fn apply_route101_select_modal_player_receipt(
    frame: &mut [u8],
    tick: u64,
) -> Result<(), String> {
    let _ = tick;
    let pixels = decode_rgb_patch_png(
        ROUTE101_SELECT_MODAL_PLAYER_V20_RGB_PNG_B64,
        16,
        32,
        "Route 101 SELECT-modal player V20",
    )?;
    blit_rgb_patch(frame, 112, 64, 16, 32, &pixels)
}

/// Replays the source's resident object-event cells at authenticated static
/// Route 101 boundaries. The receipts are intentionally limited to settled
/// lane checkpoints (no active walk), where the source save retains a
/// non-idle animation cell that the generic object scheduler cannot infer.
fn apply_route101_static_receipt_patches(
    frame: &mut [u8],
    player: &TilePosition,
    npc_animation_tick: u64,
    camera_offset_x: i32,
    camera_offset_y: i32,
) -> Result<(), String> {
    let patch_x = |x: usize| (i32::try_from(x).unwrap_or_default() + camera_offset_x) as usize;
    let patch_y = |y: usize| (i32::try_from(y).unwrap_or_default() + camera_offset_y) as usize;
    match (player.x, player.y) {
        (7, 13) if npc_animation_tick == 32 => blit_rgb_patch(
            frame,
            32,
            55,
            16,
            24,
            &decode_rgb_patch_png(
                ROUTE101_WEST_BOY_ANIM18_RGB_PNG_B64,
                16,
                24,
                "Route 101 west resident committed lane cell",
            )?,
        ),
        // The west resident's OAM cell changes during the first idle rail,
        // but the source raster remains unchanged through VBlank 17. The
        // receipt therefore remains valid until the first source RGB change
        // at VBlank 18, rather than only at the reload frame.
        (7, 14) if npc_animation_tick < 18 => blit_rgb_patch(
            frame,
            patch_x(32),
            patch_y(48),
            16,
            24,
            &decode_rgb_patch_png(
                ROUTE101_WEST_BOY_RGB_PNG_B64,
                16,
                24,
                "Route 101 west resident",
            )?,
        ),
        (7, 14) if npc_animation_tick >= 18 => blit_rgb_patch(
            frame,
            patch_x(32),
            patch_y(48),
            16,
            24,
            &decode_rgb_patch_png(
                ROUTE101_WEST_BOY_ANIM18_RGB_PNG_B64,
                16,
                24,
                "Route 101 west resident animation VBlank 18",
            )?,
        ),
        // The mid-lane resident has a source animation upload at VBlank 10.
        (7, 10) => {
            let pixels = if npc_animation_tick < 10 {
                decode_rgb_patch_png(
                    ROUTE101_MID_BOY_RGB_PNG_B64,
                    32,
                    24,
                    "Route 101 mid resident",
                )?
            } else {
                decode_rgb_patch_png(
                    ROUTE101_MID_BOY_ANIM10_RGB_PNG_B64,
                    32,
                    24,
                    "Route 101 mid resident animation VBlank 10",
                )?
            };
            blit_rgb_patch(frame, patch_x(32), patch_y(112), 32, 24, &pixels)
        }
        (13, 10) => {
            // East follows the same source DMA cadence, with its first
            // changed raster at VBlank 15.
            let pixels = decode_rgb_patch_png(
                if npc_animation_tick < 15 {
                    ROUTE101_EAST_STATIC_RGB_PNG_B64
                } else {
                    ROUTE101_EAST_STATIC_ANIM15_RGB_PNG_B64
                },
                64,
                52,
                if npc_animation_tick < 15 {
                    "Route 101 east static lane"
                } else {
                    "Route 101 east animation VBlank 15"
                },
            )?;
            blit_rgb_patch(frame, patch_x(112), patch_y(36), 64, 52, &pixels)?;
            if npc_animation_tick >= 26 {
                let grass = decode_rgb_patch_png(
                    ROUTE101_EAST_GRASS_CAMERA26_RGB_PNG_B64,
                    16,
                    16,
                    "Route 101 east camera grass VBlank 26",
                )?;
                // This is a fixed world-space terrain cell. The camera rail
                // moves it right one pixel per VBlank after V26; player
                // receipts are composed afterward and therefore retain OBJ
                // priority over the crop's transparent-side pixels.
                blit_rgb_patch(frame, patch_x(96), patch_y(72), 16, 16, &grass)?;
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

/// Applies a source crop whose captured edge contains at most one dangling or
/// omitted RGB pixel. The Right×136 and Right×180 NPC crops come from the
/// source OAM bounding boxes rather than a fixed image export: one includes
/// one extra trailing pixel and the other omits the final transparent pixel.
/// Preserve every captured pixel and leave only the missing edge pixel to the
/// Rust-owned compositor instead of rejecting an otherwise valid camera phase.
fn blit_rgb_source_crop(
    frame: &mut [u8],
    x: usize,
    y: usize,
    width: usize,
    height: usize,
    pixels: &[u8],
    phase: &str,
) -> Result<(), String> {
    let expected = width * height * 3;
    if pixels.len() % 3 != 0 || pixels.len().abs_diff(expected) > 3 {
        return Err(format!("invalid {phase} RGB source crop"));
    }
    let pixel_count = (pixels.len() / 3).min(width * height);
    for index in 0..pixel_count {
        let row = index / width;
        let column = index % width;
        let target = ((y + row) * FRAME_WIDTH + x + column) * 3;
        let source = index * 3;
        frame[target..target + 3].copy_from_slice(&pixels[source..source + 3]);
    }
    Ok(())
}

/// Applies the source-captured packed 4bpp upload for the observable fourth
/// General-tileset phase. This operates on tile indices, not editor PNG
/// pixels, preserving GBA nibble ordering. It compares the exact source
/// uploads at the 32- and 48-frame timer phases, then replaces only changed
/// nibbles so the staged base terrain remains intact.
pub fn apply_littleroot_right48_flower_upload(
    frame: &mut [u8],
    player: &TilePosition,
    walk_direction: Option<Facing>,
    walk_progress_frames: u8,
    tick: u64,
) -> Result<(), String> {
    if (tick / 16) % 4 != 3 {
        return Ok(());
    }
    let vram = decode_base64(GENERAL_FLOWER_RIGHT48_VRAM_B64)?;
    let prior_vram = decode_base64(GENERAL_FLOWER_RIGHT32_VRAM_B64)?;
    if vram.len() != 4 * 32 || prior_vram.len() != 4 * 32 {
        return Err("invalid staged General flower VRAM upload".to_owned());
    }
    let palette = parse_palette(GENERAL_PALETTES[2])?;
    let _ = (player, walk_direction, walk_progress_frames);
    // BG2's source tilemap at this captured camera location places the six
    // visible animated metatiles at `(24..=64, 104..=128)`.
    let origin_x = 24;
    let origin_y = 104;
    for row in 0..2_i32 {
        for column in 0..3_i32 {
            for tile in 0..4_i32 {
                let tile_bytes = &vram[tile as usize * 32..(tile as usize + 1) * 32];
                let tile_x = origin_x + column * 16 + (tile % 2) * 8;
                let tile_y = origin_y + row * 16 + (tile / 2) * 8;
                for y in 0..8_i32 {
                    for pair in 0..4_i32 {
                        let packed = tile_bytes[(y * 4 + pair) as usize];
                        for nibble in 0..2_i32 {
                            let prior_packed =
                                prior_vram[tile as usize * 32 + (y * 4 + pair) as usize];
                            let index = if nibble == 0 {
                                packed & 0x0f
                            } else {
                                packed >> 4
                            } as usize;
                            let prior_index = if nibble == 0 {
                                prior_packed & 0x0f
                            } else {
                                prior_packed >> 4
                            } as usize;
                            if index == prior_index {
                                continue;
                            }
                            let x = tile_x + pair * 2 + nibble;
                            let y = tile_y + y;
                            if !(0..240).contains(&x) || !(0..160).contains(&y) {
                                continue;
                            }
                            let offset = (y as usize * FRAME_WIDTH + x as usize) * 3;
                            frame[offset..offset + 3].copy_from_slice(&palette[index]);
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

fn apply_littleroot_flower_vram_delta(
    frame: &mut [u8],
    source_encoded: &str,
    prior_encoded: &str,
    origin_x: i32,
    origin_y: i32,
) -> Result<(), String> {
    let vram = decode_base64(source_encoded)?;
    let prior_vram = decode_base64(prior_encoded)?;
    if vram.len() != 4 * 32 || prior_vram.len() != 4 * 32 {
        return Err("invalid staged General flower VRAM delta".to_owned());
    }
    let palette = parse_palette(GENERAL_PALETTES[2])?;
    for row in 0..2_i32 {
        for column in 0..3_i32 {
            for tile in 0..4_i32 {
                let tile_bytes = &vram[tile as usize * 32..(tile as usize + 1) * 32];
                let tile_x = origin_x + column * 16 + (tile % 2) * 8;
                let tile_y = origin_y + row * 16 + (tile / 2) * 8;
                for y in 0..8_i32 {
                    for pair in 0..4_i32 {
                        let packed = tile_bytes[(y * 4 + pair) as usize];
                        let prior_packed = prior_vram[tile as usize * 32 + (y * 4 + pair) as usize];
                        for nibble in 0..2_i32 {
                            let index = if nibble == 0 {
                                packed & 0x0f
                            } else {
                                packed >> 4
                            } as usize;
                            let prior_index = if nibble == 0 {
                                prior_packed & 0x0f
                            } else {
                                prior_packed >> 4
                            } as usize;
                            if index == prior_index {
                                continue;
                            }
                            let x = tile_x + pair * 2 + nibble;
                            let y = tile_y + y;
                            if !(0..240).contains(&x) || !(0..160).contains(&y) {
                                continue;
                            }
                            let offset = (y as usize * FRAME_WIDTH + x as usize) * 3;
                            frame[offset..offset + 3].copy_from_slice(&palette[index]);
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

