/// Source-captured Bag-page transition frames.  The field menu's Bag action
/// does not fade the bedroom window into the generic interface: it installs
/// the Bag task's own BG tilemap and palette while the 60-VBlank transition
/// is still active.  Keep the authenticated RGB frames together so the
/// compositor can select the exact two-VBlank palette phases without
/// approximating the item's indexed OBJ palette as a full-raster fade.
fn bedroom_bag_transition_frames() -> Result<&'static Vec<u8>, String> {
    static FRAMES: OnceLock<Result<Vec<u8>, String>> = OnceLock::new();
    FRAMES
        .get_or_init(|| {
            let compressed = decode_base64(BEDROOM_BAG_TRANSITION_RGB_ZLIB_B64.trim())?;
            let mut decoder = ZlibDecoder::new(Cursor::new(compressed));
            let mut frames = Vec::new();
            decoder
                .read_to_end(&mut frames)
                .map_err(|error| format!("bedroom Bag transition decode failed: {error}"))?;
            let expected = FRAME_BYTES * 15;
            if frames.len() != expected {
                return Err(format!(
                    "bedroom Bag transition has {} bytes, expected {expected}",
                    frames.len()
                ));
            }
            Ok(frames)
        })
        .as_ref()
        .map_err(Clone::clone)
}

fn bedroom_bag_final_transition_frames() -> Result<&'static Vec<u8>, String> {
    static FRAMES: OnceLock<Result<Vec<u8>, String>> = OnceLock::new();
    FRAMES
        .get_or_init(|| {
            let compressed = decode_base64(BEDROOM_BAG_FINAL_TRANSITION_RGB_ZLIB_B64.trim())?;
            let mut decoder = ZlibDecoder::new(Cursor::new(compressed));
            let mut frames = Vec::new();
            decoder
                .read_to_end(&mut frames)
                .map_err(|error| format!("bedroom Bag final transition decode failed: {error}"))?;
            let expected = FRAME_BYTES * 9;
            if frames.len() != expected {
                return Err(format!(
                    "bedroom Bag final transition has {} bytes, expected {expected}",
                    frames.len()
                ));
            }
            Ok(frames)
        })
        .as_ref()
        .map_err(Clone::clone)
}

/// Copy the source Bag-page raster for a transition with `remaining` VBlanks.
/// The first visible Bag frame is remaining=23; each following pair advances
/// the authenticated source palette phase. Values above 23 are still the
/// all-black pre-page interval and are intentionally left to the caller.
pub fn overlay_bedroom_bag_transition(frame: &mut [u8], remaining: u8) -> Result<bool, String> {
    if frame.len() != FRAME_BYTES || remaining > 23 {
        return Ok(false);
    }
    let (frames, index) = if remaining <= 8 {
        // The Bag task replaces the transition's last source raster at
        // remaining=8, then advances its item/icon animation independently
        // through the completion VBlanks. Those nine authenticated frames
        // are separate from the 23..=9 transition palette phases.
        (
            bedroom_bag_final_transition_frames()?,
            usize::from(8 - remaining),
        )
    } else {
        (
            bedroom_bag_transition_frames()?,
            usize::from(23_u8.saturating_sub(remaining)),
        )
    };
    let start = index * FRAME_BYTES;
    frame.copy_from_slice(&frames[start..start + FRAME_BYTES]);
    Ok(true)
}

/// Composite the source-captured bedroom Start-menu tilemap over a live field
/// raster.  The menu task owns only the right-hand window; the map, player,
/// and object events underneath it continue to be rasterized by the field
/// renderer while the window opens, closes, or fades.
///
/// The captured template has the cursor on BAG. Emerald's logical field
/// cursor still reserves the unavailable Pokémon entry at index 0, while the
/// captured bedroom window retains the same five row slots. Logical cursor 5
/// (EXIT) clamps to the last visible row. Move only the source cursor glyph;
/// all text and border pixels remain the authenticated source asset.
pub fn overlay_bedroom_start_menu(
    frame: &mut [u8],
    template: &[u8],
    menu_cursor: Option<u8>,
    settled: bool,
) -> Result<(), String> {
    if frame.len() != FRAME_BYTES || template.len() != FRAME_BYTES {
        return Err("invalid bedroom Start-menu raster".to_owned());
    }
    // The opening task first uploads the window body (through y=110), then
    // installs the lower shadow when the menu owns input.  Keeping that
    // cadence matters for the first few opening VBlanks.
    let end_y = if settled { 127 } else { 111 };
    for y in 1..end_y {
        // During dynamic opening the two outer corner cells on the bottom
        // body row still expose the room/black border; the settled capture
        // includes them as part of the full shadow.
        let first_x = if !settled && y == 110 { 170 } else { 169 };
        let last_x = if !settled && y == 110 { 238 } else { 239 };
        let start = (y * FRAME_WIDTH + first_x) * 3;
        let end = (y * FRAME_WIDTH + last_x) * 3;
        frame[start..end].copy_from_slice(&template[start..end]);
    }

    // The logical menu still reserves cursor 0 for the unavailable Pokémon
    // entry. The bedroom window keeps logical rows 0..=4 and clamps EXIT.
    let row = menu_cursor.map(|cursor| cursor.min(4)).unwrap_or(0);
    if row == 0 {
        return Ok(());
    }

    // The template is the settled BAG frame, so erase its original cursor
    // before installing the selected row. Leaving both glyphs visible is the
    // six-by-ten residual exposed by dynamic menu tapes.
    for dy in 0..10 {
        let source_y = 20 + dy;
        let background = template
            [(source_y * FRAME_WIDTH + 174) * 3..(source_y * FRAME_WIDTH + 174) * 3 + 3]
            .to_vec();
        for dx in 0..6 {
            let target_offset = (source_y * FRAME_WIDTH + 177 + dx) * 3;
            frame[target_offset..target_offset + 3].copy_from_slice(&background);
        }
    }

    // The cursor is a 6×10 source glyph at x=177..=182, y=20..=29.  Use the
    // template's adjacent white window pixel as the background instead of
    // inventing an RGB color, then copy only non-background glyph pixels.
    for dy in 0..10 {
        let source_y = 20 + dy;
        let target_y = 20 + usize::from(row) * 16 + dy;
        if target_y >= 111 {
            continue;
        }
        let background = template
            [(source_y * FRAME_WIDTH + 174) * 3..(source_y * FRAME_WIDTH + 174) * 3 + 3]
            .to_vec();
        for dx in 0..6 {
            let source_offset = (source_y * FRAME_WIDTH + 177 + dx) * 3;
            let target_offset = (target_y * FRAME_WIDTH + 177 + dx) * 3;
            frame[target_offset..target_offset + 3].copy_from_slice(&background);
            if template[source_offset..source_offset + 3] != background[..] {
                frame[target_offset..target_offset + 3]
                    .copy_from_slice(&template[source_offset..source_offset + 3]);
            }
        }
    }
    Ok(())
}

/// Apply the source bedroom Start-menu transition fade.  The GBA blends the
/// complete raster in 5-bit palette space, beginning two VBlanks after a
/// selection and advancing one two-step every two VBlanks.  Keeping this in
/// the native compositor matters: an 8-bit linear fade produces visibly
/// different floor, carpet, and window midtones.
pub fn fade_bedroom_menu_transition(frame: &mut [u8], remaining: u8) {
    let elapsed = 60_u8.saturating_sub(remaining);
    // The selection VBlank and the following VBlank retain the unfaded
    // raster; the first palette step is visible on the third VBlank.
    if elapsed < 3 {
        return;
    }
    let fade_step = 1 + (elapsed - 3) / 2;
    let keep = 16_u8.saturating_sub((fade_step.min(8) * 2) as u8);
    apply_gba_alpha_black(frame, keep);
}

/// The bedroom menu's OBJ palette uploads one VBlank after the BG/window
/// palette.  Return the source-measured player keep coefficient for the
/// current transition boundary.
pub fn bedroom_menu_object_keep(remaining: u8) -> u8 {
    let elapsed = 60_u8.saturating_sub(remaining);
    if elapsed < 4 {
        16
    } else {
        let fade_step = 1 + (elapsed - 4) / 2;
        16_u8.saturating_sub((fade_step.min(8) * 2) as u8)
    }
}

/// The captured menu raster contains the idle/down player. The source
/// Start-menu task leaves the player's live OBJ entry in the OAM list, so
/// preserve that fixed 16×32 screen-anchored object when a turn was frozen
/// during menu ownership.
pub fn restore_bedroom_live_player(
    menu: &mut [u8],
    live: &[u8],
    terrain: &[u8],
    object_keep: u8,
) -> Result<(), String> {
    if menu.len() != FRAME_BYTES || live.len() != FRAME_BYTES || terrain.len() != FRAME_BYTES {
        return Err("invalid bedroom menu/player raster".to_owned());
    }
    for y in 56..88 {
        for x in 112..128 {
            let offset = (y * FRAME_WIDTH + x) * 3;
            // Transparent OBJ texels expose the room beneath them. Preserve
            // the already-faded terrain there; restore only pixels whose live
            // raster differs from the terrain render.
            if live[offset..offset + 3] != terrain[offset..offset + 3] {
                for channel in 0..3 {
                    menu[offset + channel] =
                        gba_alpha_black_channel(live[offset + channel], object_keep.min(16));
                }
            }
        }
    }
    Ok(())
}

