/// Restore the authenticated window/grass layer behind transparent pixels of
/// the selected ball's row-32 cell.  Those OBJ pixels reveal a source layer
/// that is not the generic dark label substrate.
fn apply_starter_choose_row32_backdrop(
    frame: &mut [u8],
    sprite: &SourceIndexedSheet,
    source_y: usize,
    center_x: usize,
    center_y: usize,
) {
    if source_y != 32 {
        return;
    }
    let source = STARTER_CHOOSE_LABEL_ROW32_SOURCE_RGB
        .get_or_init(|| {
            decode_rgb_patch_png(
                STARTER_CHOOSE_LABEL_ROW32_SOURCE_RGB_PNG_B64,
                112,
                32,
                "starter-choice row-32 label backdrop",
            )
            .expect("starter-choice row-32 label backdrop must decode")
        });
    let origin_x = center_x.saturating_sub(16);
    let origin_y = center_y.saturating_sub(16);
    for row in 0..32 {
        for column in 0..32 {
            let x = origin_x + column;
            let y = origin_y + row;
            if x < 124 || y < 80 || x >= FRAME_WIDTH || y >= FRAME_HEIGHT {
                continue;
            }
            let index = sprite.pixels[(source_y + row) * sprite.width + column];
            if index != 0 {
                continue;
            }
            let patch_x = x - 124;
            let patch_y = y - 80;
            let source_offset = (patch_y * 112 + patch_x) * 3;
            let offset = (y * FRAME_WIDTH + x) * 3;
            frame[offset..offset + 3].copy_from_slice(&source[source_offset..source_offset + 3]);
        }
    }
}

fn darken_starter_ball_label_overlap(
    frame: &mut [u8],
    sprite: &SourceIndexedSheet,
    source_y: usize,
    center_x: usize,
    center_y: usize,
    label_bounds: Option<(usize, usize, usize, usize)>,
    moving_shadow: bool,
) {
    // Source blended OBJ palette values for the selected ball under the
    // label window. Entries not used by the ball remain harmless defaults.
    const SHADOW_ROW0: [[u8; 3]; 16] = [
        [0, 0, 0],
        [132, 41, 49],
        [112, 37, 27],
        [94, 28, 27],
        [75, 23, 27],
        [120, 120, 125],
        [97, 97, 105],
        [75, 74, 83],
        [56, 55, 64],
        [144, 97, 101],
        [14, 32, 37],
        [33, 50, 55],
        [0, 0, 0],
        [0, 0, 0],
        [144, 144, 144],
        [0, 0, 0],
    ];
    const SHADOW_MOVING: [[u8; 3]; 16] = [
        [0, 0, 0],
        [130, 46, 27],
        [112, 37, 27],
        [94, 28, 27],
        [75, 23, 27],
        [120, 120, 125],
        [98, 97, 101],
        [75, 74, 83],
        [56, 55, 64],
        [144, 97, 101],
        [14, 32, 37],
        [33, 50, 55],
        [0, 0, 0],
        [0, 0, 0],
        [144, 144, 144],
        [0, 0, 0],
    ];
    let shadow = if !moving_shadow && source_y == 0 {
        &SHADOW_ROW0
    } else {
        &SHADOW_MOVING
    };
    let origin_x = center_x.saturating_sub(16);
    let origin_y = center_y.saturating_sub(16);
    for row in 0..32 {
        for column in 0..32 {
            let x = origin_x + column;
            let y = origin_y + row;
            let under_label = if let Some((left, top, right, bottom)) = label_bounds {
                x >= left && x < right && y >= top && y < bottom
            } else {
                x >= 124 && y >= 80
            };
            if !under_label || x >= FRAME_WIDTH || y >= FRAME_HEIGHT {
                continue;
            }
            let index = usize::from(sprite.pixels[(source_y + row) * sprite.width + column]);
            if index == 0 || index >= shadow.len() {
                continue;
            }
            let offset = (y * FRAME_WIDTH + x) * 3;
            frame[offset..offset + 3].copy_from_slice(&shadow[index]);
        }
    }
}

fn darken_starter_hand_label_overlap(
    frame: &mut [u8],
    sprite: &SourceIndexedSheet,
    origin_x: usize,
    origin_y: usize,
    label_bounds: (usize, usize, usize, usize),
    starter: StarterSpecies,
) {
    let (left, top, right, bottom) = label_bounds;
    let (source, source_x, source_y) = starter_target_label_source(starter);
    for row in 0..32 {
        for column in 0..32 {
            let x = origin_x + column;
            let y = origin_y + row;
            if x < left || x >= right || y < top || y >= bottom {
                continue;
            }
            let index = sprite.pixels[(96 + row) * sprite.width + column];
            if index == 0 || x >= FRAME_WIDTH || y >= FRAME_HEIGHT {
                continue;
            }
            let offset = (y * FRAME_WIDTH + x) * 3;
            let current = [frame[offset], frame[offset + 1], frame[offset + 2]];
            let source_offset = ((y - source_y) * 112 + (x - source_x)) * 3;
            if current == [0, 0, 0]
                && source[source_offset..source_offset + 3] == [75, 46, 41]
            {
                frame[offset..offset + 3].copy_from_slice(&source[source_offset..source_offset + 3]);
                continue;
            }
            let shadow = match current {
                [255, 255, 255] => [144, 143, 143],
                [213, 213, 222] => [121, 120, 124],
                [172, 172, 180] => [98, 97, 101],
                [131, 131, 148] => [56, 55, 64],
                [98, 98, 115] => [33, 50, 55],
                [75, 46, 41] if source[source_offset..source_offset + 3] == [0, 0, 0] => {
                    [0, 0, 0]
                }
                _ => continue,
            };
            frame[offset..offset + 3].copy_from_slice(&shadow);
        }
    }
}

/// Two transparent OBJ edge pixels are covered by the moving label BG's
/// grass tile rather than the black index in the 4bpp ball cell.  These are
/// stable source PPU masks for the authenticated post-selection rail.
fn apply_starter_choose_authenticated_edge_mask(
    frame: &mut [u8],
    starter: StarterSpecies,
    animation_frame: u8,
) {
    if animation_frame < 4 {
        return;
    }
    let pixels: &[(usize, usize)] = match starter {
        StarterSpecies::Treecko => &[(54, 72), (56, 73)],
        StarterSpecies::Mudkip => &[(171, 58), (171, 59), (170, 60), (170, 61), (169, 62), (169, 63)],
        StarterSpecies::Torchic => &[],
    };
    let color = if animation_frame == 4 {
        [0, 0, 0]
    } else {
        [79, 124, 64]
    };
    for &(x, y) in pixels {
        let offset = (y * FRAME_WIDTH + x) * 3;
        frame[offset..offset + 3].copy_from_slice(&color);
    }
    if starter == StarterSpecies::Mudkip && matches!(animation_frame, 4 | 5) {
        for &(x, y) in &[(170, 32), (171, 32), (169, 33), (168, 34)] {
            let offset = (y * FRAME_WIDTH + x) * 3;
            frame[offset..offset + 3].copy_from_slice(&[75, 46, 41]);
        }
        for &(x, y) in &[(168, 38), (169, 39), (170, 40), (171, 40)] {
            let offset = (y * FRAME_WIDTH + x) * 3;
            frame[offset..offset + 3].copy_from_slice(&[0, 0, 0]);
        }
    }
}

