/// Applies the source's measured final door-task OAM receipt.  This is a
/// genuine object-event rail (Mom/player/ball/effect slots rotate and their
/// Y coordinates advance independently), so a generic player walker cannot
/// reconstruct it from the logical destination coordinate.
fn configure_mays_house_1f_exit_oam_receipt(oam: &mut [u8], frame: u64) {
    let Some(line) = MAYS_HOUSE_1F_EXIT_OAM_5007_5096_TSV.lines().find(|line| {
        line.split_once('\t')
            .is_some_and(|(key, _)| key == frame.to_string())
    }) else {
        return;
    };
    let Some((_, encoded)) = line.split_once('\t') else {
        return;
    };
    let Some((encoded, _)) = encoded.split_once('\t') else {
        return;
    };
    let Ok(receipt) = decode_base64(encoded) else {
        return;
    };
    if receipt.len() == 64 {
        oam[..64].copy_from_slice(&receipt);
    }
}

/// Reconstruct the source-owned 1F object slots after the rival OnFrame
/// script creates May.  This map keeps the bedroom OBJ bank: May is the
/// standing 16x32 cell at tile 32/palette 10 and Mom remains the uploaded
/// tile-20 cell at the right side of the room.  Feeding these through the
/// generic outdoor sheet path produces the wrong bank/pose and visibly
/// corrupts the lower half of the room.
fn configure_mays_house_1f_rival_oam(
    oam: &mut [u8],
    player: &TilePosition,
    player_facing: Facing,
    rival: &NpcState,
    mom: &NpcState,
    npc_animation_tick: u64,
    npc_walk_starts: &[NpcWalkStart],
    hide_rival: bool,
) {
    let mut rival_x = 112 + i32::from(rival.position.x - player.x) * 16;
    let base_rival_y = 56 + i32::from(rival.position.y - player.y) * 16;
    let mut rival_y = base_rival_y;
    let mays_departure_started = npc_walk_starts.iter().any(|walk| {
        walk.id == rival.id && !walk.in_place && walk.sprite_facing == Some(Facing::Right)
    });
    let mut visual_facing = rival.facing;
    if let Some(walk) = npc_walk_starts
        .iter()
        .rev()
        .find(|walk| walk.id == rival.id)
    {
        let raw_elapsed = npc_animation_tick.saturating_sub(walk.frame) as i32;
        let duration = i32::from(walk.duration_frames.max(1));
        // The departure callback commits the next tile before its first
        // visible pixel step. Hold only an in-flight walk's first callback;
        // completed walks must remain at their destination.
        let elapsed = if mays_departure_started {
            raw_elapsed.saturating_sub(3).max(0)
        } else {
            raw_elapsed
        };
        let mays_departure_up = rival.position.x >= 3
            && rival.position.y <= 3
            && !walk.in_place
            && walk.sprite_facing == Some(Facing::Up)
            && walk.duration_frames == 16;
        let mays_departure_final_up = rival.position.x == 2
            && rival.position.y <= 1
            && !walk.in_place
            && walk.sprite_facing == Some(Facing::Up)
            && walk.duration_frames == 16;
        let mays_departure_left = rival.position.y <= 1
            && !walk.in_place
            && walk.sprite_facing == Some(Facing::Left)
            && walk.duration_frames == 16;
        // The first four-VBlank turn task begins immediately after the right
        // stride commits (x=3,y=3), but the source keeps the prior stride's
        // final three pixels visible before presenting the turn pose.
        let right_stride_tail = walk.in_place
            && walk.sprite_facing == Some(Facing::Up)
            && rival.position.x == 3
            && rival.position.y == 3
            && raw_elapsed < 4;
        if right_stride_tail {
            visual_facing = Facing::Right;
            rival_x -= 3 - raw_elapsed;
        } else if walk.in_place
            && walk.sprite_facing == Some(Facing::Left)
            && rival.position.y <= 1
            && raw_elapsed < 4
        {
            visual_facing = Facing::Up;
            rival_y += 3 - raw_elapsed;
        } else if walk.in_place
            && walk.sprite_facing == Some(Facing::Up)
            && rival.position.x == 2
            && rival.position.y <= 1
            && raw_elapsed < 4
        {
            // The west stride's three-pixel tail remains visible when the
            // next up-turn task starts.  Source V4479 therefore anchors May
            // three pixels east of the committed tile before settling.
            visual_facing = Facing::Left;
            rival_x += 3 - raw_elapsed;
        } else if mays_departure_final_up {
            // The final upward callback starts at the committed west tile,
            // but its GoFast task keeps the object four VBlanks lower before
            // translating.  Source V4483..4486 therefore holds y=40, then
            // advances one pixel per VBlank from V4487 onward.
            let motion_elapsed = raw_elapsed.saturating_sub(3).max(0).min(duration);
            rival_y += duration - motion_elapsed;
            visual_facing = walk.sprite_facing.unwrap_or(rival.facing);
        } else if mays_departure_up {
            // The source's first upward departure callback holds the
            // committed tile for three VBlanks, then advances one pixel per
            // VBlank.  Its OAM anchor is therefore one pixel lower than the
            // generic destination-relative walker at elapsed zero.
            let motion_elapsed = if rival.position.y <= 1 {
                raw_elapsed.min(duration + 3)
            } else {
                raw_elapsed.saturating_sub(3).max(0).min(duration)
            };
            rival_y += if rival.position.y <= 1 {
                duration + 3 - motion_elapsed
            } else {
                duration - motion_elapsed
            };
            visual_facing = walk.sprite_facing.unwrap_or(rival.facing);
        } else if !walk.in_place && elapsed < duration {
            visual_facing = walk.sprite_facing.unwrap_or(rival.facing);
            // The source's west GoFast callback commits the destination tile
            // before its first visible pixel, just like the east callback.
            // Hold that anchor for the callback's three-VBlank setup tail;
            // translating on raw elapsed=1 moves May one pixel too soon at
            // the first left-departure boundary (source V4464).
            let motion_elapsed = if mays_departure_left {
                raw_elapsed.saturating_sub(3).max(0).min(duration)
            } else {
                elapsed
            };
            let remaining = duration - motion_elapsed;
            match visual_facing {
                Facing::Up => rival_y += remaining - 1,
                Facing::Down => rival_y -= remaining,
                Facing::Left => rival_x += remaining,
                Facing::Right => rival_x -= remaining,
            }
        }
    }
    let mom_x = 112 + i32::from(mom.position.x - player.x) * 16;
    let mom_y = 56 + i32::from(mom.position.y - player.y) * 16;
    let mut rival_attr0 = 0x8078_u16;
    rival_attr0 = (rival_attr0 & !0x00ff) | rival_y.rem_euclid(256) as u16;
    // The template's 0x70 was the previous bedroom anchor, not an attr1
    // flag.  OR-ing it into the computed coordinate pushed May to x=240
    // (off the 240-pixel raster) as soon as the departure turn completed.
    let mut rival_attr1 = 0x8000_u16 | (rival_x.rem_euclid(512) as u16 & 0x01ff);
    // The staged side sheet is authored in the left-facing orientation. The
    // source sets OAM HFLIP for May's rightward departure walk.
    if visual_facing == Facing::Right {
        rival_attr1 |= 0x1000;
    }
    oam[0..8].copy_from_slice(&[
        rival_attr0 as u8,
        (rival_attr0 >> 8) as u8,
        rival_attr1 as u8,
        (rival_attr1 >> 8) as u8,
        0x20,
        0xa8,
        0x00,
        0x01,
    ]);
    let mom_attr0 = 0x8000_u16 | (mom_y.rem_euclid(256) as u16);
    let mom_attr1 = 0x80d0_u16 | (mom_x.rem_euclid(512) as u16 & 0x01ff);
    oam[8..16].copy_from_slice(&[
        mom_attr0 as u8,
        (mom_attr0 >> 8) as u8,
        mom_attr1 as u8,
        (mom_attr1 >> 8) as u8,
        0x14,
        0x28,
        0x00,
        0x00,
    ]);

    // The source task rotates resident OAM slots as the emotion effect and
    // May's upward walk run.  This is observable even when the logical NPC
    // coordinates are unchanged: tile-28 is the Poké Ball, while the player
    // remains the bedroom tile-0 object.  Keep the renderer's field-effect
    // overlay for the icon pixels, but preserve the source object order so
    // the ball/player do not consume each other's cells.
    let elapsed = npc_animation_tick.saturating_sub(124);
    let rival_entry = oam[0..8].to_vec();
    let mom_entry = oam[8..16].to_vec();
    let mut ball_entry = [0x58, 0x00, 0xe0, 0x40, 0x1c, 0x28, 0x00, 0x00];
    // The source's Poké Ball field effect begins its final resident-cell
    // rail at V4645: OAM X walks left one pixel per VBlank from 0xdf through
    // 0xd0, then remains at 0xd0 until the house handoff.  This is a task
    // local to the authenticated May encounter (the scene starts at V124),
    // so key it to that scene clock rather than to player coordinates.
    let ball_exit_tick = npc_animation_tick.saturating_sub(124);
    if ball_exit_tick >= 4521 {
        let ball_x = if ball_exit_tick <= 4536 {
            0xdf_u16.saturating_sub((ball_exit_tick - 4521) as u16)
        } else {
            0xd0
        };
        let ball_attr1 = (u16::from_le_bytes([ball_entry[2], ball_entry[3]]) & !0x01ff) | ball_x;
        ball_entry[2..4].copy_from_slice(&ball_attr1.to_le_bytes());
    }
    // The player's resident tile is authored west-facing.  The source's
    // GoFast east turn flips the OAM entry, independently of May's own
    // facing/rail; omitting this bit leaves the right-turn cell mirrored.
    let player_attr1 = if player_facing == Facing::Right {
        0x9070_u16
    } else {
        0x8070_u16
    };
    let player_entry = [
        0x38,
        0x80,
        player_attr1 as u8,
        (player_attr1 >> 8) as u8,
        0x00,
        0x08,
        0x00,
        0xff,
    ];
    for entry in 0..5 {
        let offset = entry * 8;
        oam[offset..offset + 2].copy_from_slice(&0x0200_u16.to_le_bytes());
    }
    let player_up_active = npc_walk_starts
        .iter()
        .rev()
        .find(|walk| walk.id == rival.id)
        .is_some_and(|walk| {
            (!walk.in_place
                && walk.sprite_facing == Some(Facing::Left)
                && npc_animation_tick >= walk.frame.saturating_add(4))
                || (walk.in_place
                    && walk.sprite_facing == Some(Facing::Up)
                    && rival.position.y <= 1)
                || (!walk.in_place
                    && walk.sprite_facing == Some(Facing::Up)
                    && rival.position.x == 2
                    && rival.position.y <= 1)
        });
    let (rival_slot, mom_slot, ball_slot, player_slot) = if player_up_active {
        // The player up-turn task takes the lower OAM slot when its blue hair
        // overlaps May's lower body; source V4474 shows those three pixels
        // winning the OBJ priority test.
        (3, 0, 1, 2)
    } else if (54..=114).contains(&elapsed) {
        (1, 2, 3, 4)
    } else if elapsed >= 139 {
        (2, 0, 1, 3)
    } else if elapsed >= 123 {
        (1, 0, 2, 3)
    } else {
        (0, 1, 2, 3)
    };
    if hide_rival {
        oam[rival_slot * 8..rival_slot * 8 + 8]
            .copy_from_slice(&[0x00, 0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]);
    } else {
        oam[rival_slot * 8..rival_slot * 8 + 8].copy_from_slice(&rival_entry);
    }
    oam[mom_slot * 8..mom_slot * 8 + 8].copy_from_slice(&mom_entry);
    oam[ball_slot * 8..ball_slot * 8 + 8].copy_from_slice(&ball_entry);
    oam[player_slot * 8..player_slot * 8 + 8].copy_from_slice(&player_entry);
}

/// During the first two post-arrival player frames the downstairs stair
/// foreground retains BG priority over a handful of player pixels. Restore
/// those pixels from the pre-OBJ terrain raster; this keeps the rule tied to
/// the map layer instead of baking source RGB values into the compositor.
fn restore_mays_house_1f_arrival_priority(
    frame: &mut [u8],
    terrain: &[u8],
    npc_animation_tick: u64,
) {
    let mask: &[(usize, usize)] = match npc_animation_tick {
        // The exit tape reaches the same stair-foreground overlap at the
        // first downstairs walk boundary (source VBlanks 100/101).  The
        // upstairs-arrival tape reaches it at its later absolute clock
        // (132/133); both are the same destination-relative PPU priority
        // task, so keep the masks grouped rather than baking an RGB patch.
        100 | 132 | 3059 => &[(122, 67), (121, 68), (122, 68), (123, 68)],
        101 | 133 | 3060 => &[(122, 67)],
        _ => &[],
    };
    for &(x, y) in mask {
        let offset = (y * FRAME_WIDTH + x) * 3;
        frame[offset..offset + 3].copy_from_slice(&terrain[offset..offset + 3]);
    }
}

/// The final north-exit walk passes behind the bedroom's upper foreground
/// rail for five VBlanks after its 16-frame stride completes.  Restore only
/// the source-owned mask from the pre-OBJ terrain; the object remains fully
/// resident in OAM and the player layer is unaffected.
fn restore_mays_house_1f_departure_priority(
    frame: &mut [u8],
    terrain: &[u8],
    departure_tail_elapsed: u64,
) {
    let side_rows: &[(usize, usize)] = &[
        (115, 37),
        (116, 37),
        (117, 37),
        (122, 37),
        (123, 37),
        (124, 37),
    ];
    let mut mask = Vec::new();
    match departure_tail_elapsed {
        1 => mask.extend_from_slice(side_rows),
        2 => {
            mask.extend_from_slice(side_rows);
            mask.extend((115..=117).map(|x| (x, 36)));
            mask.extend((122..=124).map(|x| (x, 36)));
            mask.extend((114..=125).map(|x| (x, 37)));
        }
        3..=5 => {
            mask.extend_from_slice(side_rows);
            mask.extend((115..=117).map(|x| (x, 35)));
            mask.extend((122..=124).map(|x| (x, 35)));
            mask.extend((114..=125).map(|x| (x, 36)));
            mask.extend((114..=125).map(|x| (x, 37)));
        }
        _ => return,
    }
    for (x, y) in mask {
        let offset = (y * FRAME_WIDTH + x) * 3;
        frame[offset..offset + 3].copy_from_slice(&terrain[offset..offset + 3]);
    }
}

fn render_mays_house_2f_runtime_map() -> Result<(Vec<u8>, usize, usize), String> {
    let interior = render_mays_house_2f()?;
    let border = render_house(&HOUSE_RUNTIME_BORDER, 2, 2)?;
    let width_metatiles = 9 + HOUSE_RUNTIME_BORDER_METATILES * 2;
    let height_metatiles = 8 + HOUSE_RUNTIME_BORDER_METATILES * 2;
    let width = width_metatiles * METATILE_SIZE;
    let height = height_metatiles * METATILE_SIZE;
    let inset = HOUSE_RUNTIME_BORDER_METATILES * METATILE_SIZE;
    let interior_width = 9 * METATILE_SIZE;
    let interior_height = 8 * METATILE_SIZE;
    let mut runtime = vec![0; width * height * 3];
    for y in 0..height {
        for x in 0..width {
            let target = (y * width + x) * 3;
            if (inset..inset + interior_width).contains(&x)
                && (inset..inset + interior_height).contains(&y)
            {
                let source = ((y - inset) * interior_width + (x - inset)) * 3;
                runtime[target..target + 3].copy_from_slice(&interior[source..source + 3]);
            } else {
                let border_x = (i32::try_from(x).expect("runtime width fits i32")
                    - i32::try_from(inset).expect("runtime inset fits i32"))
                .rem_euclid(32) as usize;
                let border_y = (i32::try_from(y).expect("runtime height fits i32")
                    - i32::try_from(inset).expect("runtime inset fits i32"))
                .rem_euclid(32) as usize;
                let source = (border_y * 32 + border_x) * 3;
                runtime[target..target + 3].copy_from_slice(&border[source..source + 3]);
            }
        }
    }
    Ok((runtime, width_metatiles, height_metatiles))
}

