fn render_world_view_with_dynamic_objects_and_tv_state_and_running_with_camera_impl(
    map_id: MapId,
    player: &TilePosition,
    player_gender: PlayerGender,
    facing: Facing,
    walk_direction: Option<Facing>,
    walk_progress_frames: u8,
    npc_animation_tick: u64,
    npcs: &[NpcState],
    npc_walk_starts: &[NpcWalkStart],
    tv_screen_on: bool,
    player_running: bool,
    running_step_uses_second_foot: bool,
    player_in_place_faster_elapsed: Option<u8>,
    mays_camera_follow_y: i16,
    littleroot_house_exit_handoff: bool,
    field_ready_sprite_upload: bool,
) -> Result<Vec<u8>, String> {
    // `TurnOffTVScreen` mutates the active map's television metatile.  The
    // downstairs segment is intentionally replayed in the rival's Mays
    // House 1F while Brendan is the player, so gender is not a safe proxy for
    // map ownership here.  Carry the script-owned boolean for either house;
    // unrelated maps retain their authored tiles.
    let active_home_tv_screen_on = match map_id {
        MapId::BrendansHouse1F | MapId::MaysHouse1F => tv_screen_on,
        _ => true,
    };
    render_world_view_with_dynamic_objects_and_player_visibility(
        map_id,
        player,
        player_gender,
        facing,
        walk_direction,
        walk_progress_frames,
        npc_animation_tick,
        npcs,
        npc_walk_starts,
        true,
        player_running,
        running_step_uses_second_foot,
        player_in_place_faster_elapsed,
        active_home_tv_screen_on,
        None,
        0,
        mays_camera_follow_y,
        littleroot_house_exit_handoff,
        field_ready_sprite_upload,
    )
}

/// Source-specific compositor for the first Mays House 1F frame sequence
/// after the upstairs stair warp.  The object layer has its own authenticated
/// OAM cadence, while the map camera remains one metatile low until the
/// arrival movement catches up.
pub fn render_mays_house_1f_arrival(
    player_gender: PlayerGender,
    player: &TilePosition,
    facing: Facing,
    npc_animation_tick: u64,
    arrival_start_frame: u64,
    npcs: &[NpcState],
    npc_walk_starts: &[NpcWalkStart],
    mays_camera_follow_y: i16,
) -> Result<Vec<u8>, String> {
    // `TurnOffTVScreen` has already run before this upstairs checkpoint; the
    // downstairs arrival therefore uses the off-screen metatile even though
    // the generic world default still starts with TV enabled.
    let active_home_tv_screen_on = false;
    let arrival_camera_follow = mays_camera_follow_y;
    let arrival_walk_direction = (arrival_camera_follow > 0).then_some(Facing::Down);
    render_world_view_with_dynamic_objects_and_player_y_offset(
        MapId::MaysHouse1F,
        player,
        player_gender,
        facing,
        arrival_walk_direction,
        0,
        npc_animation_tick,
        npcs,
        npc_walk_starts,
        true,
        false,
        false,
        None,
        active_home_tv_screen_on,
        0,
        None,
        mays_house_1f_arrival_map_y_offset(npc_animation_tick.saturating_sub(arrival_start_frame)),
        Some(npc_animation_tick.saturating_sub(arrival_start_frame)),
        mays_camera_follow_y,
        false,
        false,
    )
}

