/// Replays the authenticated player OBJ upload during the bedroom-origin
/// destination fade. The source updates this 16x32 cell independently of the
/// background palette; applying it after the fade keeps the player from being
/// darkened or shifted by the generic terrain compositor.
pub fn apply_mays_house_exit_arrival_player_receipt(
    frame: &mut [u8],
    source_frame: u64,
) -> Result<(), String> {
    if !(5115..=5134).contains(&source_frame) {
        return Ok(());
    }
    let sheet = decode_rgb_patch_png(
        MAYS_HOUSE_EXIT_ARRIVAL_PLAYER_SHEET_PNG_B64,
        320,
        32,
        "Mays-house exit arrival player RGB receipt sheet",
    )?;
    blit_rgb_sheet_frame(
        frame,
        112,
        56,
        16,
        32,
        320,
        usize::try_from(source_frame - 5115).unwrap_or_default(),
        &sheet,
    )
}

