    #[test]
    fn bedroom_north_stair_fade_uses_source_two_vblank_steps_and_obj_lag() {
        // Fade starts at V41. V41--42 retain the unfaded raster; BG fades on
        // V43 and OBJ catches up on V44. The same cadence continues through
        // V48, exactly matching the measured source boundary sequence.
        let expected = [
            (41, None),
            (42, None),
            (43, Some((14, 16))),
            (44, Some((14, 14))),
            (45, Some((12, 14))),
            (46, Some((12, 12))),
            (47, Some((10, 12))),
            (48, Some((10, 10))),
        ];
        for (frame, expected) in expected {
            assert_eq!(
                bedroom_stair_fade_coefficients(frame, Some(41))
                    .map(|coefficients| (coefficients.background_keep, coefficients.object_keep)),
                expected,
                "unexpected north-stair palette phase at V{frame}",
            );
        }
    }

    #[test]
    fn bedroom_stair_fade_quantizes_in_gba_five_bit_space() {
        let mut pixels = vec![255, 127, 8];
        apply_gba_alpha_black(&mut pixels, 14);
        // 31 * 14 / 16 = 27 -> 222; 15 * 14 / 16 = 13 -> 107; and a
        // one-step source channel truncates to zero before expansion.
        assert_eq!(pixels, vec![222, 107, 0]);
    }

    #[test]
    fn bedroom_stair_priority_restore_never_leaks_below_its_source_mask() {
        let mut frame = vec![0; FRAME_BYTES];
        let terrain = vec![0x7f; FRAME_BYTES];
        restore_bedroom_north_stair_priority(&mut frame, &terrain, 67);

        let pixel = |buffer: &[u8], x: usize, y: usize| {
            let offset = (y * FRAME_WIDTH + x) * 3;
            buffer[offset..offset + 3].to_vec()
        };
        assert_eq!(pixel(&frame, 117, 66), vec![0x7f; 3]);
        assert_eq!(pixel(&frame, 118, 67), vec![0x7f; 3]);
        assert_eq!(pixel(&frame, 123, 67), vec![0; 3]);
        assert_eq!(pixel(&frame, 114, 68), vec![0; 3]);
    }

    #[test]
    fn settled_battler_oam_keeps_the_wild_grass_player_scanline_distinct() {
        let (wild, _) = build_emerald_settled_command_ppu(
            crate::world::StarterSpecies::Torchic,
            5,
            15,
            19,
            "POOCHYENA",
            2,
            13,
            13,
            true,
        )
        .expect("wild settled battle PPU must stage");
        let (trainer, _) = build_emerald_settled_command_ppu(
            crate::world::StarterSpecies::Torchic,
            6,
            15,
            21,
            "MUDKIP",
            5,
            20,
            20,
            false,
        )
        .expect("trainer settled battle PPU must stage");
        let wild_attr0 = u16::from_le_bytes([wild.oam[9 * 8], wild.oam[9 * 8 + 1]]);
        let trainer_attr0 = u16::from_le_bytes([trainer.oam[9 * 8], trainer.oam[9 * 8 + 1]]);
        assert_eq!(wild_attr0 & 0xff, 54);
        assert_eq!(trainer_attr0 & 0xff, 53);
    }

    #[test]
    fn move_selection_uses_the_source_bg0_window_ranges_and_scroll() {
        let (memory, registers) =
            build_emerald_battle_move_ui_ppu(0, &[("SCRATCH", 35), ("GROWL", 40)])
                .expect("move selection PPU must stage");
        assert_eq!(registers.bg_offsets[1], 320);
        let entry = |x, y| {
            let offset = gba_text_bg_entry_offset(registers, 0, x, y).expect("BG0 entry");
            u16::from_le_bytes([memory.vram[offset], memory.vram[offset + 1]])
        };
        // Authenticated Route 103 receipt: six palette-5 dynamic ranges at
        // 0x290/0x2a0/0x300..0x330, with the regular cursor in slot one.
        assert_eq!(entry(1, 55), 1);
        assert_eq!(entry(2, 55), 0x5300);
        assert_eq!(entry(11, 55), 0x5310);
        assert_eq!(entry(2, 57), 0x5320);
        assert_eq!(entry(11, 57), 0x5330);
        assert_eq!(entry(21, 55), 0x5290);
        assert_eq!(entry(21, 57), 0x52a0);
    }

    #[test]
    fn settled_healthbox_obj_text_follows_logical_party_values() {
        let (full, _) = build_emerald_settled_command_ppu(
            crate::world::StarterSpecies::Torchic,
            5,
            15,
            19,
            "POOCHYENA",
            2,
            13,
            13,
            true,
        )
        .expect("settled battle PPU must stage");
        let (damaged, _) = build_emerald_settled_command_ppu(
            crate::world::StarterSpecies::Torchic,
            5,
            13,
            19,
            "POOCHYENA",
            2,
            7,
            13,
            true,
        )
        .expect("damaged settled battle PPU must stage");
        // The name lives independently of dynamic health fields, while the
        // source HP digits and six fill tiles are re-uploaded from state.
        assert_eq!(
            &full.vram[0x10000 + 0x40..0x10000 + 0x40 + 192],
            &damaged.vram[0x10000 + 0x40..0x10000 + 0x40 + 192]
        );
        assert_ne!(
            &full.vram[0x10000 + 0x2000..0x10000 + 0x2000 + 544],
            &damaged.vram[0x10000 + 0x2000..0x10000 + 0x2000 + 544]
        );
        assert_ne!(
            &full.vram[0x10000 + 0xb00..0x10000 + 0xb00 + 64],
            &damaged.vram[0x10000 + 0xb00..0x10000 + 0xb00 + 64]
        );
    }
